import time
from functools import wraps

def medir(f):
    @wraps(f)
    def envoltura(*args, **kwargs):
        inicio = time.perf_counter()
        try:
            return f(*args, **kwargs)
        finally:
            print(f"{f.__name__}: {time.perf_counter() - inicio:.3f}s")
    return envoltura

