def reintentar(veces=3):
    def decorador(f):
        @wraps(f)
        def envoltura(*args, **kwargs):
            for intento in range(veces):
                try:
                    return f(*args, **kwargs)
                except OSError:
                    if intento == veces - 1:
                        raise
        return envoltura
    return decorador

