class Sesion:
    def __init__(self, plan):
        self.plan = plan
        self.inicio = time.time()
        self.respuestas = []

    def registrar(self, nota):
        self.respuestas.append(nota)

    def terminada(self):
        return len(self.respuestas) >= self.plan.tarjetas

